using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Linq;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            s.OpenPage("conclusions");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            Action<float, float> click = (x, y) =>
            {
                var p = new Vector2(x * Screen.width / 1200 / 1.25f, y * Screen.height / 800 / 1.25f + 55);
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
            };
            int i = 0;
            double next = EditorApplication.timeSinceStartup + .6;
            EditorApplication.CallbackFunction f = null;
            f = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + .7;
                if (i++ == 0)
                {
                    click(272, 714);
                    w.SendEvent(new Event{type = EventType.ScrollWheel, mousePosition = new Vector2(750, 520), delta = new Vector2(0, 100)});
                }
                else if (i == 2)
                {
                    ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/conclusion-ui-confirmed.png");
                }
                else if (i == 3)
                {
                    click(650, 710);
                }
                else
                {
                    EditorApplication.update -= f;
                    var ok = s.data.finalized && s.data.conclusions.All(c => c.choice == 0);
                    File.WriteAllText("Test/KetQua/investigation_r103/conclusion-ui.txt", "Synthetic UI confirm/save; finalized=" + s.data.finalized + " all choices insufficient=" + s.data.conclusions.All(c => c.choice == 0) + " claim=" + s.data.conclusions[0].claim + "\n" + (ok ? "PASS" : "FAIL"));
                    ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/conclusion-ui-final.png");
                }
            };
            EditorApplication.update += f;
            r.Log("UI consent and save test");
        }
    }
}

